fn is_prime(n: i8) -> bool {
    // Step 1: Check if n is less than 2
    if n < 2 {
        return false;
    }

    // Step 2: Iterate through potential divisors from 2 to n - 1
    for k in 2..n {
        // Step 3: Check if n is divisible by k
        if n % k == 0 {
            return false; // Found a divisor, so n is not prime
        }
    }

    // Step 4: No divisors found, n is prime
    true
}